console.log("GO360 script cargado");(function(){const LOGO_INTRO_KEY="go360-logo-intro";const LOGO_DURATION=1200;const NAVIGATION_DELAY=48;const LOGO_TARGET_WIDTH_RATIO=0.66;const LOGO_GAP_RATIO=0.05;const LOGO_BASELINE_RATIO=0.51;const prefersReducedMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;let isLogoAnimating=false;document.addEventListener("DOMContentLoaded",()=>{initMobileMenu();initProfileMenu();initDraftReset();initLogoOrchestration();});function initMobileMenu(){const btn=document.querySelector(".top-bar__hamburger");const menu=document.querySelector(".mobile-menu");if(!btn||!menu){return;}
btn.addEventListener("click",()=>{menu.style.display=menu.style.display==="block"?"none":"block";});}
function initProfileMenu(){const profileBtn=document.querySelector(".top-bar__profile-link");const profileMenu=document.querySelector(".top-bar__profile-menu");if(!profileBtn||!profileMenu){return;}
profileBtn.addEventListener("click",(event)=>{event.stopPropagation();profileMenu.classList.toggle("visible");});document.addEventListener("click",()=>{profileMenu.classList.remove("visible");});profileMenu.addEventListener("click",(event)=>{event.stopPropagation();});}
function initDraftReset(){const newLinks=document.querySelectorAll("[data-reset-draft]");newLinks.forEach((link)=>{link.addEventListener("click",()=>{localStorage.removeItem("go_draft_id");localStorage.removeItem("go_draft_uuid");});});}
function initLogoOrchestration(){const svg=document.querySelector(".site-logo__svg");if(svg){updateLogoVariables(svg);}
const wrapper=document.querySelector(".site-logo-wrapper--auth");if(!wrapper){return;}
const shouldAnimate=shouldAnimateIntro();if(shouldAnimate&&!prefersReducedMotion){animateLogoIntro(wrapper);}else{wrapper.classList.remove("is-horizontal");wrapper.classList.remove("is-preload");}
const form=document.querySelector(".auth-form");if(form){form.addEventListener("submit",(event)=>{if(event.defaultPrevented||isLogoAnimating){return;}
event.preventDefault();startLogoNavigation(wrapper,()=>{const nativeSubmit=HTMLFormElement.prototype.submit;nativeSubmit.call(form);});});}
const links=document.querySelectorAll(".login-page a[href], .register-page a[href]");links.forEach((link)=>{if(link.closest(".site-logo-wrapper")){return;}
if(link.dataset.logoTransition==="skip"){return;}
if(link.target&&link.target!=="_self"){return;}
const url=toAbsoluteURL(link.getAttribute("href"));if(!url){return;}
if(url.origin!==window.location.origin){return;}
if(url.href===window.location.href){return;}
link.addEventListener("click",(event)=>{if(event.defaultPrevented||isLogoAnimating){return;}
event.preventDefault();startLogoNavigation(wrapper,()=>{window.location.href=url.href;});});});}
function shouldAnimateIntro(){if(prefersReducedMotion){sessionStorage.removeItem(LOGO_INTRO_KEY);return false;}
const stored=sessionStorage.getItem(LOGO_INTRO_KEY);if(stored==="1"){sessionStorage.removeItem(LOGO_INTRO_KEY);return true;}
try{if(document.referrer){const referrerUrl=new URL(document.referrer);if(referrerUrl.origin===window.location.origin){return true;}}}catch(error){}
return false;}
function animateLogoIntro(wrapper){wrapper.classList.add("is-preload");wrapper.classList.add("is-horizontal");requestAnimationFrame(()=>{wrapper.classList.remove("is-preload");requestAnimationFrame(()=>{wrapper.classList.remove("is-horizontal");});});}
function animateLogoForward(wrapper){return new Promise((resolve)=>{wrapper.classList.remove("is-horizontal");wrapper.classList.remove("is-preload");void wrapper.offsetWidth;requestAnimationFrame(()=>{wrapper.classList.add("is-horizontal");});window.setTimeout(resolve,LOGO_DURATION);});}
function startLogoNavigation(wrapper,navigate){sessionStorage.setItem(LOGO_INTRO_KEY,"1");if(prefersReducedMotion||!wrapper){if(wrapper){wrapper.classList.add("is-horizontal");wrapper.classList.remove("is-preload");}
navigate();return;}
if(isLogoAnimating){return;}
isLogoAnimating=true;const finalize=()=>{isLogoAnimating=false;};const proceedNavigation=()=>{const startTransition=document.startViewTransition?document.startViewTransition.bind(document):null;if(startTransition){startTransition(()=>{navigate();}).finished.finally(finalize);return;}
navigate();finalize();};animateLogoForward(wrapper).then(()=>{window.setTimeout(proceedNavigation,NAVIGATION_DELAY);}).catch(()=>{finalize();proceedNavigation();});}
function toAbsoluteURL(href){if(!href){return null;}
try{return new URL(href,window.location.href);}catch(error){return null;}}
function updateLogoVariables(svg){try{const text360=svg.querySelector("#texto-360");const textVO=svg.querySelector("#texto-VO");const viewBox=svg.viewBox&&svg.viewBox.baseVal;if(!text360||!textVO||!viewBox){return;}
const styles=getComputedStyle(document.documentElement);const targetWidthRatio=parseFloat(styles.getPropertyValue("--logo-target-width-ratio"))||LOGO_TARGET_WIDTH_RATIO;const gapRatio=parseFloat(styles.getPropertyValue("--logo-gap-ratio"))||LOGO_GAP_RATIO;const baselineRatio=parseFloat(styles.getPropertyValue("--logo-baseline-ratio"))||LOGO_BASELINE_RATIO;const box360=text360.getBBox();const boxVO=textVO.getBBox();const width360=box360.width;const widthVO=boxVO.width;const height360=box360.height;const heightVO=boxVO.height;const gap=viewBox.width*gapRatio;const combinedWidth=width360+widthVO;const desiredWidth=Math.max(gap,viewBox.width*targetWidthRatio-gap);const scale=Math.max(0.5,Math.min(1.2,desiredWidth/combinedWidth));const totalWidth=combinedWidth*scale+gap;const startX=viewBox.x+(viewBox.width-totalWidth)/2;const targetCenterY=viewBox.y+viewBox.height*baselineRatio;const targetCenter360X=startX+(width360*scale)/2;const targetCenterVOX=startX+width360*scale+gap+(widthVO*scale)/2;const originCenter360X=box360.x+width360/2;const originCenter360Y=box360.y+height360/2;const originCenterVOX=boxVO.x+widthVO/2;const originCenterVOY=boxVO.y+heightVO/2;const rootStyle=document.documentElement.style;rootStyle.setProperty("--logo-scale",scale.toFixed(3));rootStyle.setProperty("--logo-dx-360",`${(targetCenter360X-originCenter360X).toFixed(2)}px`);rootStyle.setProperty("--logo-dy-360",`${(targetCenterY-originCenter360Y).toFixed(2)}px`);rootStyle.setProperty("--logo-dx-vo",`${(targetCenterVOX-originCenterVOX).toFixed(2)}px`);rootStyle.setProperty("--logo-dy-vo",`${(targetCenterY-originCenterVOY).toFixed(2)}px`);}catch(error){console.error("GO360 logo metrics",error);}}})();